import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": None}, {"converted": True}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions_not_groups():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "c": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"c": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (6, 9)])
def test_trailing_window(days, expected):
    assert conversions_in_window([2, 3, 4], days) == expected


def test_parse_fields_and_skip_non_data_lines():
    assert parse_session_log(["", " \t", "  # comment", " a , 2 , 0 ", "b,3, "]) == [
        {"id": "a", "day": 2, "converted": False},
        {"id": "b", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("bad", ["a,1", "a,1,0,extra", "a,two,1"])
def test_parser_reports_input_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", "", "ok,3,1", bad])


def test_dedupe_keeps_last_record_for_duplicate_id_and_sorts():
    original, b, c, replacement = parse_session_log(["a,9,0", "b,2,1", "c,1,0", "a,2,1"])
    assert dedupe_sessions([original, b, c, replacement]) == [c, replacement, b]


def test_daily_counts_include_gaps_and_ignore_outside_days():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


def test_campaign_summary_uses_calendar_days():
    groups = {"a": parse_session_log(["x,1,1", "y,2,1", "z,5,0"]), "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 1}
    assert campaign_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ranking_and_rate_order():
    groups = {"z": [{"converted": True}], "b": [{"converted": False}], "empty": [],
              "a": [{"converted": True}]}
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert list(conversion_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0)
    ]


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1], 0), ([1, 0, 2, 3, -1, 1], 2)])
def test_longest_positive_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected

